events_sorted <- events |> arrange(Date)

event_items <- lapply(seq_len(nrow(events_sorted)), function(i) {
  e <- events_sorted[i, ]

  meta_parts <- c(
    format(e$Date, "%d %B %Y"),
    if (!is.na(e$Organization) && nzchar(e$Organization)) e$Organization,
    if (!is.na(e$Location)     && nzchar(e$Location))     e$Location,
    if (!is.na(e$Time)         && nzchar(e$Time))         e$Time,
    if (!is.na(e$Fee)          && nzchar(as.character(e$Fee))) paste0("Fee: ", e$Fee)
  )

  links <- tagList(
    if (!is.na(e[["Agenda Link"]]) && nzchar(e[["Agenda Link"]]))
      tags$a("Agenda", href = e[["Agenda Link"]], style = "margin-right:8px;"),
    if (!is.na(e[["Registration Link"]]) && nzchar(e[["Registration Link"]]))
      tags$a("Registration", href = e[["Registration Link"]])
  )

  tags$li(
    tags$strong(e$Title),
    tags$br(),
    tags$span(paste(meta_parts, collapse = " · "),
              style = "color:#555; font-size:0.9em;"),
    tags$br(),
    links,
    style = "margin-bottom:0.8em;"
  )
})

htmltools::tags$ul(tagList(event_items), style = "list-style:none; padding-left:0;")
